import backtrader as bt
import math


class BreakoutEMATrailingStrategy(bt.Strategy):
    params = (
        ("ema_period", 8),
        ("entry_level", 179.33),
        ("take_profit", 184.89),
        ("final_take_profit", 192.95),
        ("risk_fraction", 0.02),
    )

    def __init__(self):
        self.ema = bt.indicators.ExponentialMovingAverage(
            self.data.close, period=self.p.ema_period
        )
        self.order = None
        self.order_action = None
        self.trailing_stop = None
        self.initial_position_size = None
        self.first_take_profit_done = False

    def notify_order(self, order):
        if order.status == order.Completed:
            if order.isbuy():
                self.initial_position_size = order.executed.size
                self.first_take_profit_done = False
                self.trailing_stop = order.executed.price - float(self.ema[0])
            elif self.order_action == "first_take_profit":
                self.first_take_profit_done = True

            if not self.position:
                self.trailing_stop = None
                self.initial_position_size = None
                self.first_take_profit_done = False

            self.order = None
            self.order_action = None
        elif order.status in (order.Canceled, order.Margin, order.Rejected):
            self.order = None
            self.order_action = None

    def next(self):
        if self.order:
            return

        close = float(self.data.close[0])
        ema = float(self.ema[0])

        if not self.position:
            if close > self.p.entry_level:
                risk_capital = float(self.broker.getvalue()) * self.p.risk_fraction
                size = math.floor(risk_capital / ema)
                if size > 0:
                    self.order_action = "entry"
                    self.order = self.buy(size=size)
            return

        self.trailing_stop = max(self.trailing_stop, close - ema)

        if not self.first_take_profit_done and float(self.data.high[0]) >= self.p.take_profit:
            self.order_action = "first_take_profit"
            self.order = self.sell(size=self.initial_position_size * 0.5)
        elif self.first_take_profit_done and float(self.data.high[0]) >= self.p.final_take_profit:
            self.order_action = "final_take_profit"
            self.order = self.close()
        elif float(self.data.low[0]) <= self.trailing_stop:
            self.order_action = "trailing_stop"
            self.order = self.close()
